CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_state (id INTEGER PRIMARY KEY CHECK (id = 1), body TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id TEXT PRIMARY KEY, t TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, resource TEXT NOT NULL, note TEXT NOT NULL, detail TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT, 'Audit is append-only'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT, 'Audit is append-only'); END;
CREATE TABLE IF NOT EXISTS storm_runs (id TEXT PRIMARY KEY, status TEXT NOT NULL, input TEXT NOT NULL, fault_snapshot TEXT NOT NULL, result TEXT, error TEXT, actor TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS triage_overrides (id TEXT PRIMARY KEY, storm_run_id TEXT NOT NULL REFERENCES storm_runs(id), asset TEXT NOT NULL, position INTEGER NOT NULL, reason TEXT NOT NULL, actor TEXT NOT NULL, t TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cases (id TEXT PRIMARY KEY, fault_id TEXT NOT NULL UNIQUE, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS guidance (id TEXT PRIMARY KEY, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suggestions (id TEXT PRIMARY KEY, fault_id TEXT NOT NULL, body TEXT NOT NULL, t TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_feedback (id TEXT PRIMARY KEY, suggestion_id TEXT NOT NULL REFERENCES suggestions(id), body TEXT NOT NULL, actor TEXT NOT NULL, t TEXT NOT NULL);
